window.obterConfigSituacaoContrato = function(sitRaw) {
    const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
    const s = normStr(sitRaw);
    if (s === 'CONTRATO ESTORNADO' || s === 'ESTORNADO') {
        return { nome: 'CONTRATO ESTORNADO', cor: 'GREY', bg: '#f1f5f9', text: '#475569', border: '#cbd5e1', status: 'Fechado', icon: 'ph-arrow-counter-clockwise', ocultoLista: true };
    }
    if (!s || s === 'EM ELABORACAO' || s === 'AGUARDANDO ASSINATURA' || s === 'APROVADA' || s === 'APROVADO') {
        return CONTRATO_SITUACOES_CONFIG[0];
    }
    if (s === 'CONTRATO DIGITAL ASSINADO' || s === 'CONTRATO ASSINADO/ENTREGA LIBERADA') {
        return CONTRATO_SITUACOES_CONFIG.find(c => c.nome === 'CONTRATO ASSINADO') || CONTRATO_SITUACOES_CONFIG[2];
    }
    const exact = CONTRATO_SITUACOES_CONFIG.find(c => normStr(c.nome) === s);
    if (exact) return exact;
    if (s === 'REPROVADA' || s === 'REPROVADO' || s === 'CANCELADA' || s === 'CANCELADO') {
        return CONTRATO_SITUACOES_CONFIG.find(c => c.nome === 'REPROVADO | CANCELADO') || CONTRATO_SITUACOES_CONFIG[5];
    }
    return { nome: String(sitRaw || 'EM ELABORAÇÃO').toUpperCase(), cor: 'DEFAULT', bg: '#f1f5f9', text: '#475569', border: '#cbd5e1', status: 'Aberto', icon: 'ph-circle' };
};

window.propostaTemContratoGerado = function(prop) {
    if (!prop) return false;
    const tipoNorm = String(prop.tipo || '').trim().toUpperCase().replace(/^PROPOSTA\s+/i, '');
    if (tipoNorm === 'ADITIVO') return false;
    return Boolean(prop.contrato && String(prop.contrato).trim());
};

window.contratoFoiEstornado = function(prop) {
    if (!prop) return false;
    const sitNorm = String(prop.situacao_contrato || '')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toUpperCase().replace(/\s+/g, ' ').trim();
    return sitNorm === 'CONTRATO ESTORNADO' || sitNorm === 'ESTORNADO';
};

window.propostaVirouContrato = function(prop) {
    if (!prop) return false;
    const tipoNorm = String(prop.tipo || '').trim().toUpperCase().replace(/^PROPOSTA\s+/i, '');
    if (tipoNorm === 'ADITIVO') return false;
    const faseUp = String(prop.fase_negociacao || '').trim().toUpperCase();
    return faseUp === 'APROVADA';
};

window.contratoEstaEmElaboracao = function(prop) {
    if (!prop) return true;
    const sitNorm = String(prop.situacao_contrato || '')
        .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
        .toUpperCase().replace(/\s+/g, ' ').trim();
    return !sitNorm || sitNorm === 'EM ELABORACAO' || sitNorm === 'AGUARDANDO ASSINATURA' || sitNorm === 'APROVADA' || sitNorm === 'APROVADO';
};

window.propostaPodeMudarParaReprovada = function(prop) {
    if (!prop) return true;
    const faseUp = String(prop.fase_negociacao || '').trim().toUpperCase();
    if (faseUp === 'APROVADA') return false;
    if (!window.propostaTemContratoGerado(prop)) return true;
    return window.contratoFoiEstornado(prop);
};

window.situacaoContratoEhAtiva = function(sitRaw) {
    const cfg = window.obterConfigSituacaoContrato(sitRaw);
    return Boolean(cfg && String(cfg.status || '').toUpperCase() === 'ATIVO');
};

window.renderBadgeSituacaoContratoHtml = function(sitRaw, mostrarStatusTipo = true) {
    const cfg = window.obterConfigSituacaoContrato(sitRaw);
    const stUpper = String(cfg.status || 'Aberto').toUpperCase();
    const stPillStyle = stUpper === 'ATIVO'
        ? 'background:#dcfce7; color:#15803d; border:1px solid #bbf7d0;'
        : (stUpper === 'FECHADO'
            ? 'background:#f1f5f9; color:#475569; border:1px solid #cbd5e1;'
            : 'background:#ffedd5; color:#c2410c; border:1px solid #fed7aa;');
    return `<span style="display:inline-flex; align-items:center; gap:5px; flex-wrap:wrap; justify-content:flex-start;">
        <span style="background:${cfg.bg}; color:${cfg.text}; border:1px solid ${cfg.border}; padding:2px 9px; border-radius:999px; font-size:0.72rem; font-weight:800; white-space:nowrap; display:inline-flex; align-items:center; gap:4px;">
            <i class="ph ${cfg.icon || 'ph-circle'}" style="font-size:0.82rem;"></i> ${cfg.nome}
        </span>
        ${mostrarStatusTipo ? `<span style="${stPillStyle} padding:1px 7px; border-radius:999px; font-size:0.68rem; font-weight:800; white-space:nowrap;">${cfg.status}</span>` : ''}
    </span>`;
};

window.avaliarBloqueioSituacaoContratoOpcao = function(cfgAlvo, sitAtualRaw) {
    if (!cfgAlvo) return { disabled: false, title: '' };
    const normStr = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().replace(/\s+/g, ' ').trim();
    const sitAtuCfg = window.obterConfigSituacaoContrato(sitAtualRaw !== undefined ? sitAtualRaw : (document.getElementById('prop-fase')?.value || ''));
    const sitAtu = normStr(sitAtuCfg && sitAtuCfg.nome);
    const alvo = normStr(cfgAlvo.nome);

    if (cfgAlvo.somenteAutomatico) {
        return {
            disabled: true,
            title: 'Definido automaticamente ao clicar em Baixar PDF, Enviar WhatsApp, Enviar E-mail ou Enviar para Assinatura via Assinafy'
        };
    }

    // "ENTREGUE - LIBERADO PARA FATURAMENTO" apenas clicável após o contrato estar em "CONTRATO ASSINADO"
    if (alvo === 'ENTREGUE - LIBERADO PARA FATURAMENTO') {
        const permitido = sitAtu === 'CONTRATO ASSINADO' || sitAtu === 'ENTREGUE - LIBERADO PARA FATURAMENTO';
        if (!permitido) {
            return {
                disabled: true,
                title: 'Disponível apenas após o contrato estar com a situação CONTRATO ASSINADO'
            };
        }
    }

    // "SOLICITAÇÃO DE RETIRADA EM ANDAMENTO" apenas clicável após o contrato estar em "CONTRATO ASSINADO" (ou NÃO ASSINA CONTRATO - ENTREGA LIBERADA)
    if (alvo === 'SOLICITACAO DE RETIRADA EM ANDAMENTO') {
        const permitido = sitAtu === 'CONTRATO ASSINADO' || sitAtu === 'NAO ASSINA CONTRATO - ENTREGA LIBERADA' || sitAtu === 'ENTREGUE - LIBERADO PARA FATURAMENTO' || sitAtu === 'SOLICITACAO DE RETIRADA EM ANDAMENTO';
        if (!permitido) {
            return {
                disabled: true,
                title: 'Disponível apenas após o contrato estar com a situação CONTRATO ASSINADO'
            };
        }
    }

    // "ENCERRADO | CONCLUÍDO" apenas clicável após o contrato estar assinado ou em retirada
    if (alvo === 'ENCERRADO | CONCLUIDO') {
        const permitido = sitAtu === 'CONTRATO ASSINADO'
            || sitAtu === 'NAO ASSINA CONTRATO - ENTREGA LIBERADA'
            || sitAtu === 'ENTREGUE - LIBERADO PARA FATURAMENTO'
            || sitAtu === 'SOLICITACAO DE RETIRADA EM ANDAMENTO'
            || sitAtu === 'ENCERRADO | CONCLUIDO';
        if (!permitido) {
            return {
                disabled: true,
                title: 'Disponível apenas após o contrato estar com a situação CONTRATO ASSINADO'
            };
        }
    }

    return { disabled: false, title: '' };
};

window.reconstruirOpcoesMenuSituacaoContrato = function(sitAtualRaw) {
    if (window._modoTelaComercial !== 'contrato') return;
    const sitVal = sitAtualRaw !== undefined ? sitAtualRaw : (document.getElementById('prop-fase')?.value || '');
    const sitSelNome = window.obterConfigSituacaoContrato(sitVal).nome;
    const sel = document.getElementById('prop-fase');
    if (sel) {
        sel.innerHTML = CONTRATO_SITUACOES_CONFIG.filter(cfg => !cfg.ocultoContrato).map(cfg => {
            const isSel = sitSelNome.toUpperCase() === cfg.nome.toUpperCase();
            const bloq = window.avaliarBloqueioSituacaoContratoOpcao(cfg, sitVal);
            return `<option value="${cfg.nome}" ${isSel ? 'selected' : ''} ${bloq.disabled ? `disabled title="${_escHtmlProp(bloq.title)}"` : ''}>${cfg.nome} (${cfg.status.toUpperCase()})</option>`;
        }).join('');
        sel.value = sitSelNome;
    }
    const menu = document.getElementById('prop-fase-custom-menu');
    if (menu) {
        menu.innerHTML = CONTRATO_SITUACOES_CONFIG.filter(cfg => !cfg.ocultoContrato).map(cfg => {
            const nomeEsc = cfg.nome.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
            const bloq = window.avaliarBloqueioSituacaoContratoOpcao(cfg, sitVal);
            const isDisCtr = Boolean(bloq.disabled);
            const titleDisCtr = bloq.title ? `title="${_escHtmlProp(bloq.title)}"` : '';
            return `<div onclick="window.selecionarFasePropostaCustom('${nomeEsc}', ${isDisCtr ? 'true' : 'false'}, event)"
                ${titleDisCtr}
                style="padding:6px 8px; border-radius:6px; cursor:${isDisCtr ? 'not-allowed' : 'pointer'}; opacity:${isDisCtr ? '0.48' : '1'}; display:flex; align-items:center; justify-content:flex-start; transition:background 0.12s;"
                onmouseover="if(!${isDisCtr}) this.style.background='#f1f5f9'" onmouseout="this.style.background='transparent'">
                ${window.renderBadgeSituacaoContratoHtml(cfg.nome, true)}
            </div>`;
        }).join('');
    }
};

window.atualizarBadgeSituacaoContratoForm = function(val) {
    const v = val !== undefined ? val : (document.getElementById('prop-fase')?.value || '');
    const el = document.getElementById('prop-situacao-contrato-badge');
    if (el) {
        el.innerHTML = window._modoTelaComercial === 'contrato'
            ? ''
            : '';
    }
    const btnBadge = document.getElementById('prop-fase-custom-btn-badge');
    if (btnBadge) {
        btnBadge.innerHTML = window._modoTelaComercial === 'contrato'
            ? window.renderBadgeSituacaoContratoHtml(v, true)
            : window.renderBadgeFaseNegociacaoHtml(v);
    }
    if (window._modoTelaComercial === 'contrato' && typeof window.reconstruirOpcoesMenuSituacaoContrato === 'function') {
        window.reconstruirOpcoesMenuSituacaoContrato(v);
    }
};

window.toggleDropdownFaseProposta = function(event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }
    const sel = document.getElementById('prop-fase');
    const btn = document.getElementById('prop-fase-custom-btn');
    if ((sel && sel.disabled) || (btn && btn.disabled)) return;
    if (window._modoTelaComercial === 'contrato' && typeof window.reconstruirOpcoesMenuSituacaoContrato === 'function') {
        window.reconstruirOpcoesMenuSituacaoContrato();
    }
    const menu = document.getElementById('prop-fase-custom-menu');
    if (!menu) return;
    menu.style.display = menu.style.display === 'block' ? 'none' : 'block';
};

window.selecionarFasePropostaCustom = function(valor, disabled, event) {
    if (event) {
        event.preventDefault();
        event.stopPropagation();
    }
    if (disabled) return;
    const sel = document.getElementById('prop-fase');
    if (sel) {
        sel.value = valor;
    }
    window.atualizarBadgeSituacaoContratoForm(valor);
    if (typeof window.toggleMotivoReprovacao === 'function') {
        window.toggleMotivoReprovacao(valor);
    }
    if (typeof window.marcarPropostaComoEditada === 'function') {
        window.marcarPropostaComoEditada({ preservarFase: true });
    }
    const menu = document.getElementById('prop-fase-custom-menu');
    if (menu) menu.style.display = 'none';
};

if (!window._listenerCloseFaseCustomMenu && typeof document !== 'undefined') {
    window._listenerCloseFaseCustomMenu = true;
    document.addEventListener('click', (e) => {
        const wrap = document.getElementById('prop-fase-custom-wrap');
        const menu = document.getElementById('prop-fase-custom-menu');
        if (menu && menu.style.display === 'block' && wrap && !wrap.contains(e.target)) {
            menu.style.display = 'none';
        }
    });
}

let _propostasData = [];
if (typeof window !== 'undefined' && !Object.getOwnPropertyDescriptor(window, '_propostasData')) {
    Object.defineProperty(window, '_propostasData', {
        get: () => _propostasData,
        set: (v) => { _propostasData = Array.isArray(v) ? v : []; },
        configurable: true
    });
}
let _dashboardStatsData = [];
let _manutencoesData = [];
let _veiculosData = [];
let _clientesData = [];
let _propostasEditandoId = null;
window._modoTelaComercial = window._modoTelaComercial || 'proposta';
window._propostasEditandoId_proposta = null;
window._propostasEditandoId_contrato = null;
window.sincronizarModoComercialComAbaAtiva = function() {
    if (typeof appOpenTabs !== 'undefined' && Array.isArray(appOpenTabs)) {
        const abaAtiva = appOpenTabs.find(t => t && t.active);
        if (abaAtiva) {
            if (abaAtiva.target === 'comercial-contratos') {
                window._modoTelaComercial = 'contrato';
            } else if (abaAtiva.target === 'comercial-proposta') {
                window._modoTelaComercial = 'proposta';
            }
        }
    }
    return window._modoTelaComercial === 'contrato' ? 'contrato' : 'proposta';
};
let _propRegiaoIdentificada = '';
let _currentPropostaTab = 'form'; // 'lista', 'form' ou 'cadastro-cliente'
let _clienteEditandoId = null;
let _clienteContatos = [];
let _clientesCache = [];
if (typeof window !== 'undefined' && !Object.getOwnPropertyDescriptor(window, '_clientesCache')) {
    Object.defineProperty(window, '_clientesCache', {
        get: () => _clientesCache,
        set: (v) => { _clientesCache = Array.isArray(v) ? v : []; },
        configurable: true
    });
}

// Variáveis de estado para o cadastro de contatos
