window._garantirEstruturaResponsaveisContrato = function() {
    if (!window._propResponsaveisContrato || typeof window._propResponsaveisContrato !== 'object') {
        window._propResponsaveisContrato = { nfe: [], cobranca: [], os: [], instalacao: '' };
    }
    ['nfe', 'cobranca', 'os'].forEach(k => {
        if (!Array.isArray(window._propResponsaveisContrato[k])) window._propResponsaveisContrato[k] = [];
    });
    if (typeof window._propResponsaveisContrato.instalacao !== 'string') {
        window._propResponsaveisContrato.instalacao = String(window._propResponsaveisContrato.instalacao || '');
    }
    return window._propResponsaveisContrato;
};

window.renderizarResponsaveisContratoChips = function() {
    const st = window._garantirEstruturaResponsaveisContrato();
    ['nfe', 'cobranca', 'os'].forEach(tipo => {
        const box = document.getElementById(`prop-resp-chips-${tipo}`);
        if (!box) return;
        const arr = st[tipo] || [];
        if (!arr.length) {
            box.innerHTML = `<span style="font-size:0.74rem; color:#94a3b8; font-style:italic;">Nenhum responsável selecionado.</span>`;
            return;
        }
        box.innerHTML = arr.map((txt, idx) => `
            <span style="display:inline-flex; align-items:center; gap:6px; background:#fff; border:1px solid #a5b4fc; border-radius:6px; padding:3px 9px; font-size:0.75rem; font-weight:700; color:#312e81; box-shadow:0 1px 2px rgba(79,70,229,0.06);">
                <span>${_escHtmlProp(txt)}</span>
                <button type="button" onclick="window.removerResponsavelContrato('${tipo}', ${idx})" title="Remover responsável" style="background:transparent; border:none; color:#dc2626; cursor:pointer; padding:0 2px; font-size:0.9rem; font-weight:800; line-height:1;">&times;</button>
            </span>
        `).join('');
    });
    const boxInst = document.getElementById('prop-resp-chips-instalacao');
    const inpInst = document.getElementById('prop-resp-inp-instalacao');
    const valInst = String(st.instalacao || '').trim();
    if (inpInst && document.activeElement !== inpInst) {
        inpInst.value = '';
    }
    if (boxInst) {
        if (!valInst) {
            boxInst.innerHTML = `<span style="font-size:0.74rem; color:#94a3b8; font-style:italic;">Nenhum contato de instalação selecionado.</span>`;
        } else {
            boxInst.innerHTML = `
                <span style="display:inline-flex; align-items:center; gap:6px; background:#fff; border:1px solid #818cf8; border-radius:6px; padding:3px 9px; font-size:0.75rem; font-weight:700; color:#312e81; box-shadow:0 1px 2px rgba(79,70,229,0.08);">
                    <span>${_escHtmlProp(valInst)}</span>
                    <button type="button" onclick="window.removerResponsavelContrato('instalacao', 0)" title="Limpar contato de instalação" style="background:transparent; border:none; color:#dc2626; cursor:pointer; padding:0 2px; font-size:0.9rem; font-weight:800; line-height:1;">&times;</button>
                </span>
            `;
        }
    }
};

window._montarRotuloContatoRespContrato = function(c, tipo) {
    if (!c) return '';
    const nome = String(c.nome || '').trim();
    const email = String(c.email || '').trim();
    const tel = String(c.celular || c.telefone || '').trim();
    if (tipo === 'instalacao') {
        return [nome, tel || email].filter(Boolean).join(' - ');
    }
    if (tipo === 'nfe' || tipo === 'cobranca') {
        return [nome, email || tel].filter(Boolean).join(' - ');
    }
    return [nome, tel || email].filter(Boolean).join(' - ');
};

window._obterElDropdownRespContrato = function(tipo) {
    return document.getElementById(`prop-resp-drop-${tipo}`) || document.getElementById(`prop-resp-dd-${tipo}`);
};

window.abrirDropdownRespContrato = async function(tipo, mostrarTodos) {
    ['nfe', 'cobranca', 'os', 'instalacao'].forEach(t => {
        if (t !== tipo) {
            const other = window._obterElDropdownRespContrato(t);
            if (other) other.style.display = 'none';
        }
    });
    const rawCli = document.getElementById('prop-cliente')?.value?.trim() || '';
    const clienteNome = typeof window.limparPrefixoGrupoCliente === 'function'
        ? window.limparPrefixoGrupoCliente(rawCli)
        : rawCli.replace(/^[💎🥇🥈🥉]\s*/, '').trim();
    if (clienteNome && (window._ultimoClienteContatosCarregado !== clienteNome || !Array.isArray(window._contatosDoClientePropostaAtual) || !window._contatosDoClientePropostaAtual.length)) {
        if (typeof window._obterDadosContatosClienteProposta === 'function') {
            await window._obterDadosContatosClienteProposta(clienteNome);
        }
    }
    const inp = document.getElementById(`prop-resp-inp-${tipo}`);
    const termo = mostrarTodos ? '' : (inp ? inp.value : '');
    window.filtrarDropdownRespContrato(tipo, termo);
};

window.toggleDropdownRespContrato = function(tipo, ev) {
    if (ev && ev.stopPropagation) ev.stopPropagation();
    const dd = window._obterElDropdownRespContrato(tipo);
    if (dd && dd.style.display === 'block') {
        dd.style.display = 'none';
        return;
    }
    window.abrirDropdownRespContrato(tipo, true);
    const inp = document.getElementById(`prop-resp-inp-${tipo}`);
    if (inp) inp.focus();
};

window.filtrarDropdownRespContrato = function(tipo, termoRaw) {
    const dd = window._obterElDropdownRespContrato(tipo);
    if (!dd) return;
    const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
    const q = norm(termoRaw);
    const contatos = Array.isArray(window._contatosDoClientePropostaAtual) ? window._contatosDoClientePropostaAtual : [];
    const st = window._garantirEstruturaResponsaveisContrato();
    const selecionadosAtuais = tipo === 'instalacao'
        ? (st.instalacao ? [st.instalacao] : [])
        : (Array.isArray(st[tipo]) ? st[tipo] : []);
    const selecionadosNorm = selecionadosAtuais.map(s => norm(s)).filter(Boolean);
    const selecionadosNomesNorm = selecionadosAtuais.map(s => norm(String(s || '').split(' - ')[0])).filter(Boolean);

    const filtrados = contatos.filter(c => {
        const rotuloC = norm(window._montarRotuloContatoRespContrato(c, tipo));
        const nomeC = norm(c.nome || '');
        if ((rotuloC && selecionadosNorm.includes(rotuloC)) || (nomeC && (selecionadosNorm.includes(nomeC) || selecionadosNomesNorm.includes(nomeC)))) {
            return false;
        }
        if (!q) return true;
        const alvo = norm(`${c.nome || ''} ${c.email || ''} ${c.celular || ''} ${c.telefone || ''} ${c.cargo || ''} ${c.departamento || ''}`);
        return alvo.includes(q);
    });
    if (!filtrados.length) {
        const txtDig = String(termoRaw || '').trim();
        const txtDigNorm = norm(txtDig);
        const jaSelTxt = txtDigNorm && (selecionadosNorm.includes(txtDigNorm) || selecionadosNomesNorm.includes(txtDigNorm));
        dd.innerHTML = (txtDig && !jaSelTxt)
            ? `<div onmousedown="event.preventDefault(); window.selecionarContatoRespDropdown('${tipo}', '${_escHtmlProp(txtDig).replace(/'/g, "\\'")}')" style="padding:8px 12px; font-size:0.78rem; color:#4338ca; font-weight:700; cursor:pointer;">+ Selecionar "${_escHtmlProp(txtDig)}"</div>`
            : `<div style="padding:8px 12px; font-size:0.76rem; color:#94a3b8;">${contatos.length > 0 && selecionadosAtuais.length > 0 ? 'Todos os contatos do cliente já foram selecionados neste campo.' : 'Nenhum contato cadastrado para o cliente. Clique no botão + amarelo ao lado para cadastrar.'}</div>`;
        dd.style.display = 'block';
        return;
    }
    dd.innerHTML = filtrados.map(c => {
        const rotulo = window._montarRotuloContatoRespContrato(c, tipo);
        const sub = [c.cargo || c.departamento, c.email, c.celular || c.telefone].filter(Boolean).join(' • ');
        const rotuloSafe = _escHtmlProp(rotulo).replace(/'/g, "\\'");
        return `
            <div onmousedown="event.preventDefault(); window.selecionarContatoRespDropdown('${tipo}', '${rotuloSafe}')"
                 style="padding:7px 11px; border-bottom:1px solid #f1f5f9; cursor:pointer; transition:background 0.12s;"
                 onmouseover="this.style.background='#eef2ff'" onmouseout="this.style.background='transparent'">
                <div style="font-size:0.78rem; font-weight:700; color:#1e293b;">${_escHtmlProp(c.nome || rotulo)}</div>
                ${sub ? `<div style="font-size:0.7rem; color:#64748b;">${_escHtmlProp(sub)}</div>` : ''}
            </div>
        `;
    }).join('');
    dd.style.display = 'block';
};

window.selecionarContatoRespDropdown = function(tipo, textoContato) {
    const val = String(textoContato || '').trim();
    const dd = window._obterElDropdownRespContrato(tipo);
    if (dd) dd.style.display = 'none';
    if (!val) return;
    const st = window._garantirEstruturaResponsaveisContrato();
    const inp = document.getElementById(`prop-resp-inp-${tipo}`);
    if (tipo === 'instalacao') {
        st.instalacao = val;
        if (inp) inp.value = '';
    } else {
        if (!st[tipo].includes(val)) {
            st[tipo].push(val);
        }
        if (inp) inp.value = '';
    }
    window.renderizarResponsaveisContratoChips();
    if (typeof window.atualizarQuadroAssinaturaDigitalDom === 'function') window.atualizarQuadroAssinaturaDigitalDom();
    if (typeof window.marcarPropostaComoEditada === 'function') window.marcarPropostaComoEditada();
};

window.adicionarResponsavelContrato = function(tipo) {
    const inp = document.getElementById(`prop-resp-inp-${tipo}`);
    const val = String(inp?.value || '').trim();
    const dd = window._obterElDropdownRespContrato(tipo);
    if (dd) dd.style.display = 'none';
    if (!val) {
        if (inp) inp.focus();
        return;
    }
    const st = window._garantirEstruturaResponsaveisContrato();
    if (tipo === 'instalacao') {
        st.instalacao = val;
        if (inp) inp.value = '';
    } else {
        if (!st[tipo].includes(val)) {
            st[tipo].push(val);
        }
        if (inp) inp.value = '';
    }
    window.renderizarResponsaveisContratoChips();
    if (typeof window.atualizarQuadroAssinaturaDigitalDom === 'function') window.atualizarQuadroAssinaturaDigitalDom();
    if (typeof window.marcarPropostaComoEditada === 'function') window.marcarPropostaComoEditada();
};

window.removerResponsavelContrato = function(tipo, idx) {
    const st = window._garantirEstruturaResponsaveisContrato();
    if (tipo === 'instalacao') {
        st.instalacao = '';
        const inp = document.getElementById('prop-resp-inp-instalacao');
        if (inp) inp.value = '';
    } else if (Array.isArray(st[tipo])) {
        st[tipo].splice(idx, 1);
    }
    window.renderizarResponsaveisContratoChips();
    if (typeof window.atualizarQuadroAssinaturaDigitalDom === 'function') window.atualizarQuadroAssinaturaDigitalDom();
    if (typeof window.marcarPropostaComoEditada === 'function') window.marcarPropostaComoEditada();
};

if (!window._propRespContratoOutsideListenerBound) {
    window._propRespContratoOutsideListenerBound = true;
    document.addEventListener('mousedown', (ev) => {
        ['nfe', 'cobranca', 'os', 'instalacao'].forEach(tipo => {
            const wrap = document.getElementById(`prop-resp-wrap-${tipo}`);
            const dd = window._obterElDropdownRespContrato(tipo);
            if (dd && dd.style.display === 'block' && wrap && !wrap.contains(ev.target)) {
                dd.style.display = 'none';
            }
        });
    });
}

/* ── Quadro ANEXOS do Contrato (upload múltiplo para Cloudflare R2 + edição de título antes/depois) ── */
window._anexosContratoCache = [];

window._formatarTamanhoBytesAnexoContrato = function(bytes) {
    const b = Number(bytes || 0);
    if (!b || b <= 0) return '';
    if (b < 1024) return `${b} B`;
    if (b < 1024 * 1024) return `${(b / 1024).toFixed(1)} KB`;
    return `${(b / (1024 * 1024)).toFixed(2)} MB`;
};

window._iconePorArquivoAnexoContrato = function(nomeArquivo, mimeType) {
    const ext = String(nomeArquivo || '').split('.').pop().toLowerCase();
    const mime = String(mimeType || '').toLowerCase();
    if (ext === 'pdf' || mime.includes('pdf')) return { icon: 'ph-file-pdf', color: '#dc2626', bg: '#fef2f2', label: 'PDF', kind: 'pdf' };
    if (['png', 'jpg', 'jpeg', 'webp', 'gif', 'bmp', 'svg'].includes(ext) || mime.startsWith('image/')) return { icon: 'ph-image', color: '#0284c7', bg: '#f0f9ff', label: (ext || 'IMG').toUpperCase(), kind: 'image' };
    if (['mp4', 'webm', 'mov', 'avi', 'mkv'].includes(ext) || mime.startsWith('video/')) return { icon: 'ph-video-camera', color: '#7c3aed', bg: '#f5f3ff', label: (ext || 'VID').toUpperCase(), kind: 'video' };
    if (['mp3', 'wav', 'ogg', 'm4a'].includes(ext) || mime.startsWith('audio/')) return { icon: 'ph-speaker-high', color: '#0891b2', bg: '#ecfeff', label: (ext || 'AUD').toUpperCase(), kind: 'audio' };
    if (['xls', 'xlsx', 'csv'].includes(ext) || mime.includes('spreadsheet') || mime.includes('excel')) return { icon: 'ph-file-xls', color: '#16a34a', bg: '#f0fdf4', label: (ext || 'XLS').toUpperCase(), kind: 'doc' };
    if (['doc', 'docx'].includes(ext) || mime.includes('word')) return { icon: 'ph-file-doc', color: '#2563eb', bg: '#eff6ff', label: (ext || 'DOC').toUpperCase(), kind: 'doc' };
    if (['ppt', 'pptx'].includes(ext) || mime.includes('presentation')) return { icon: 'ph-file-ppt', color: '#ea580c', bg: '#fff7ed', label: (ext || 'PPT').toUpperCase(), kind: 'doc' };
    if (['zip', 'rar', '7z'].includes(ext) || mime.includes('zip') || mime.includes('compressed')) return { icon: 'ph-file-zip', color: '#ca8a04', bg: '#fefce8', label: (ext || 'ZIP').toUpperCase(), kind: 'doc' };
    return { icon: 'ph-file-text', color: '#475569', bg: '#f8fafc', label: (ext && ext.length <= 5 ? ext.toUpperCase() : 'ARQ'), kind: 'doc' };
};

window._obterUrlArquivoAnexoContrato = function(anexoId, download = false, propIdOverride = null) {
    const propId = Number(propIdOverride || _propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId || !anexoId) return '';
    const token = window.currentToken || localStorage.getItem('erp_token') || localStorage.getItem('rh_token') || localStorage.getItem('token') || sessionStorage.getItem('token') || '';
    return `/api/propostas/${propId}/anexos-contrato/${encodeURIComponent(String(anexoId))} /arquivo`.replace(' /arquivo', '/arquivo') + `?${download ? 'download=1&' : ''}token=${encodeURIComponent(token)}`;
};

window._gerarHtmlMiniaturaAnexoContrato = function(anexo, tamanhoPx = 56) {
    const a = anexo || {};
    const ic = window._iconePorArquivoAnexoContrato(a.nome_arquivo, a.mime_type);
    const idJsSafe = _escHtmlProp(String(a.id || '')).replace(/'/g, "\\'");
    const urlInline = window._obterUrlArquivoAnexoContrato(a.id, false, a.proposta_id);
    const w = Number(tamanhoPx) || 56;
    const h = Number(tamanhoPx) || 56;
    const badgeExt = `<span style="position:absolute; bottom:2px; right:2px; background:${ic.color}; color:#fff; font-size:0.56rem; font-weight:800; padding:1px 4px; border-radius:3px; line-height:1.1; pointer-events:none; box-shadow:0 1px 2px rgba(0,0,0,0.2);">${_escHtmlProp(ic.label || 'ARQ')}</span>`;

    if (ic.kind === 'image' && urlInline) {
        return `
            <div onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', false)" title="Clique para visualizar ${_escHtmlProp(a.nome_arquivo || 'imagem')}"
                style="width:${w}px; height:${h}px; border-radius:8px; overflow:hidden; position:relative; flex-shrink:0; border:1.5px solid #cbd5e1; background:${ic.bg}; cursor:pointer; display:flex; align-items:center; justify-content:center; box-shadow:0 1px 3px rgba(15,23,42,0.08);">
                <img src="${_escHtmlProp(urlInline)}" alt="${_escHtmlProp(a.nome_arquivo || '')}"
                    style="width:100%; height:100%; object-fit:cover; display:block;"
                    onerror="this.style.display='none'; if(this.nextElementSibling) this.nextElementSibling.style.display='flex';">
                <div style="display:none; width:100%; height:100%; align-items:center; justify-content:center; flex-direction:column; color:${ic.color};">
                    <i class="ph ${ic.icon}" style="font-size:1.35rem;"></i>
                </div>
                ${badgeExt}
            </div>
        `;
    }

    if (ic.kind === 'pdf' && urlInline) {
        return `
            <div onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', false)" title="Clique para visualizar ${_escHtmlProp(a.nome_arquivo || 'PDF')}"
                style="width:${w}px; height:${h}px; border-radius:8px; overflow:hidden; position:relative; flex-shrink:0; border:1.5px solid #fca5a5; background:#ffffff; cursor:pointer; display:flex; align-items:center; justify-content:center; box-shadow:0 1px 3px rgba(15,23,42,0.08);">
                <iframe src="${_escHtmlProp(urlInline)}#toolbar=0&navpanes=0&scrollbar=0&view=FitH" tabindex="-1"
                    style="width:220px; height:220px; border:none; transform:scale(${(w / 220).toFixed(3)}); transform-origin:top left; pointer-events:none; position:absolute; top:0; left:0; background:#fff;"></iframe>
                ${badgeExt}
            </div>
        `;
    }

    if (ic.kind === 'video' && urlInline) {
        return `
            <div onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', false)" title="Clique para abrir ${_escHtmlProp(a.nome_arquivo || 'vídeo')}"
                style="width:${w}px; height:${h}px; border-radius:8px; overflow:hidden; position:relative; flex-shrink:0; border:1.5px solid #c4b5fd; background:#0f172a; cursor:pointer; display:flex; align-items:center; justify-content:center; box-shadow:0 1px 3px rgba(15,23,42,0.08);">
                <video src="${_escHtmlProp(urlInline)}" muted preload="metadata" style="width:100%; height:100%; object-fit:cover; pointer-events:none;"></video>
                ${badgeExt}
            </div>
        `;
    }

    // Demais formatos (Word, Excel, PowerPoint, ZIP, Áudio, TXT, etc.): miniatura estilo página de documento com dobra, linhas e selo colorido do formato
    return `
        <div onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', false)" title="Clique para abrir ${_escHtmlProp(a.nome_arquivo || 'documento')}"
            style="width:${w}px; height:${h}px; border-radius:8px; overflow:hidden; position:relative; flex-shrink:0; border:1.5px solid #cbd5e1; background:linear-gradient(145deg, #ffffff 0%, ${ic.bg} 100%); cursor:pointer; display:flex; flex-direction:column; align-items:center; justify-content:center; box-shadow:0 1px 3px rgba(15,23,42,0.08);">
            <div style="position:absolute; top:0; right:0; width:12px; height:12px; background:#e2e8f0; border-bottom-left-radius:4px;"></div>
            <i class="ph ${ic.icon}" style="font-size:1.45rem; color:${ic.color}; margin-bottom:6px;"></i>
            ${badgeExt}
        </div>
    `;
};

window.carregarAnexosContratoAtivo = async function(propIdOpcional) {
    const propId = Number(propIdOpcional || _propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId) {
        window._anexosContratoCache = [];
        window.renderizarListaAnexosContrato([]);
        return;
    }
    try {
        const rows = await apiGet(`/propostas/${propId}/anexos-contrato`);
        window._anexosContratoCache = Array.isArray(rows) ? rows : [];
        window.renderizarListaAnexosContrato(window._anexosContratoCache);
    } catch (e) {
        console.warn('[ANEXOS_CONTRATO] Erro ao carregar anexos:', e);
    }
};

window.renderizarListaAnexosContrato = function(lista) {
    const arr = Array.isArray(lista) ? lista : (window._anexosContratoCache || []);
    const badge = document.getElementById('prop-anexos-contrato-count-badge');
    if (badge) badge.textContent = `${arr.length} anexo(s)`;

    const wrap = document.getElementById('prop-anexos-contrato-lista-wrap');
    if (!wrap) return;

    if (!arr.length) {
        wrap.innerHTML = `
            <div style="text-align:center; color:#94a3b8; font-size:0.82rem; padding:0.85rem; background:#ffffff; border:1px dashed #cbd5e1; border-radius:8px;">
                Nenhum documento anexado a este contrato ainda.
            </div>
        `;
        return;
    }

    const fmtDataHoraBr = (dtStr) => {
        const s = String(dtStr || '').trim();
        if (!s) return '';
        const m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:[T\s](\d{2}):(\d{2}))?/);
        if (!m) return s;
        return `${m[3]}/${m[2]}/${m[1]}${m[4] ? ` às ${m[4]}:${m[5]}` : ''}`;
    };

    wrap.innerHTML = `
        <div style="display:flex; flex-direction:column; gap:8px;">
            ${arr.map((a, idx) => {
                const ic = window._iconePorArquivoAnexoContrato(a.nome_arquivo, a.mime_type);
                const tamStr = window._formatarTamanhoBytesAnexoContrato(a.tamanho);
                const dtStr = fmtDataHoraBr(a.criado_em);
                const ehAuto = Boolean(a.automatico || String(a.id || '').startsWith('auto_'));
                const idJsSafe = _escHtmlProp(String(a.id || '')).replace(/'/g, "\\'");
                const metaParts = [a.nome_arquivo, tamStr, dtStr ? `${ehAuto ? 'Assinado em' : 'Incluído em'} ${dtStr}` : '', a.criado_por ? `por ${a.criado_por}` : ''].filter(Boolean);
                const badgeTipoAuto = ehAuto
                    ? (a.tipo_automatico === 'aditivo_assinado'
                        ? `<span style="font-size:0.7rem; font-weight:800; color:#854d0e; background:#fef9c3; border:1px solid #eab308; padding:2px 8px; border-radius:999px; white-space:nowrap;">Aditivo Assinado • Automático</span>`
                        : `<span style="font-size:0.7rem; font-weight:800; color:#0f766e; background:#ccfbf1; border:1px solid #5eead4; padding:2px 8px; border-radius:999px; white-space:nowrap;">Contrato Assinado • Automático</span>`)
                    : '';
                const thumbHtml = typeof window._gerarHtmlMiniaturaAnexoContrato === 'function'
                    ? window._gerarHtmlMiniaturaAnexoContrato(a, 54)
                    : `<div style="width:44px; height:44px; border-radius:8px; background:${ic.bg}; color:${ic.color}; display:flex; align-items:center; justify-content:center; flex-shrink:0; border:1px solid rgba(0,0,0,0.06);">
                        <i class="ph ${ic.icon}" style="font-size:1.25rem;"></i>
                    </div>`;
                return `
                    <div style="background:${ehAuto ? '#f8fafc' : '#ffffff'}; border:1px solid ${ehAuto ? '#99f6e4' : '#e2e8f0'}; border-radius:8px; padding:0.55rem 0.75rem; display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap;">
                        <div style="display:flex; align-items:center; gap:10px; flex:1 1 320px; min-width:240px;">
                            ${thumbHtml}
                            <div style="flex:1; min-width:180px;">
                                <div style="display:flex; align-items:center; gap:6px; flex-wrap:wrap;">
                                    <span style="font-size:0.72rem; font-weight:800; color:#854d0e; background:#fef9c3; border:1px solid #fde047; padding:1px 6px; border-radius:4px; white-space:nowrap;">#${idx + 1}</span>
                                    ${ehAuto
                                        ? `<span style="font-size:0.84rem; font-weight:800; color:#0f172a;">${_escHtmlProp(a.titulo || a.nome_arquivo || 'Documento Assinado')}</span>${badgeTipoAuto}`
                                        : `<input type="text" id="prop-anexo-titulo-item-${a.id}" value="${_escHtmlProp(a.titulo || '')}"
                                            placeholder="Escreva o título deste anexo..."
                                            onblur="window.salvarTituloAnexoContrato('${idJsSafe}', this.value)"
                                            onkeydown="if(event.key==='Enter'){ event.preventDefault(); this.blur(); }"
                                            style="flex:1; min-width:160px; padding:0.38rem 0.55rem; border:1px solid #cbd5e1; border-radius:6px; font-size:0.82rem; font-weight:600; color:#0f172a; background:#fff; box-sizing:border-box; text-transform:none !important;">
                                        <span id="prop-anexo-status-${a.id}" style="font-size:0.72rem; font-weight:700; color:#16a34a; white-space:nowrap; display:none;">Salvo ✓</span>`}
                                </div>
                                <div style="font-size:0.73rem; color:#64748b; margin-top:3px; word-break:break-all;">
                                    ${_escHtmlProp(metaParts.join(' • '))}
                                </div>
                            </div>
                        </div>
                        <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
                            <button type="button" onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', false)" title="Visualizar anexo em nova guia"
                                style="background:#eff6ff; color:#1d4ed8; border:1px solid #bfdbfe; padding:5px 10px; border-radius:6px; font-size:0.76rem; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:4px;">
                                <i class="ph ph-eye" style="font-size:0.92rem;"></i> Visualizar
                            </button>
                            <button type="button" onclick="window.abrirArquivoAnexoContrato('${idJsSafe}', true)" title="Baixar anexo"
                                style="background:#f0fdf4; color:#15803d; border:1px solid #bbf7d0; padding:5px 10px; border-radius:6px; font-size:0.76rem; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:4px;">
                                <i class="ph ph-download-simple" style="font-size:0.92rem;"></i> Baixar
                            </button>
                            ${!ehAuto ? `<button type="button" onclick="window.excluirAnexoContrato('${idJsSafe}', '${_escHtmlProp(a.nome_arquivo || 'anexo').replace(/'/g, "\\'")}')" title="Remover anexo do contrato"
                                style="background:#fef2f2; color:#dc2626; border:1px solid #fecaca; padding:5px 9px; border-radius:6px; font-size:0.76rem; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:4px;">
                                <i class="ph ph-trash" style="font-size:0.92rem;"></i>
                            </button>` : ''}
                        </div>
                    </div>
                `;
            }).join('')}
        </div>
    `;
};

window.enviarArquivosAnexosContrato = async function(fileList) {
    const files = Array.from(fileList || []);
    const fileInp = document.getElementById('prop-anexo-contrato-files-inp');
    if (!files.length) return;

    const propId = Number(_propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId) {
        if (typeof Swal !== 'undefined') Swal.fire('Atenção', 'Salve o contrato antes de incluir anexos.', 'warning');
        if (fileInp) fileInp.value = '';
        return;
    }

    const tituloInp = document.getElementById('prop-anexo-contrato-titulo-inp');
    const tituloInicial = tituloInp ? String(tituloInp.value || '').trim() : '';
    const btnUpload = document.getElementById('btn-prop-anexo-contrato-upload');
    const htmlOrig = btnUpload ? btnUpload.innerHTML : '';

    try {
        if (btnUpload) {
            btnUpload.disabled = true;
            btnUpload.innerHTML = `<i class="ph ph-spinner ph-spin"></i> Enviando ${files.length} arquivo(s)...`;
        }
        const fd = new FormData();
        files.forEach(f => fd.append('arquivos', f));
        if (tituloInicial) fd.append('titulo', tituloInicial);

        const token = window.currentToken || localStorage.getItem('erp_token') || localStorage.getItem('rh_token') || localStorage.getItem('token') || sessionStorage.getItem('token') || '';
        const resp = await fetch(`/api/propostas/${propId}/anexos-contrato`, {
            method: 'POST',
            headers: token ? { 'Authorization': `Bearer ${token}` } : {},
            body: fd
        });
        const data = await resp.json().catch(() => ({}));
        if (!resp.ok || data.error) {
            throw new Error(data.error || `Falha no envio (HTTP ${resp.status})`);
        }
        if (tituloInp) tituloInp.value = '';
        if (fileInp) fileInp.value = '';

        await window.carregarAnexosContratoAtivo(propId);

        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`${files.length} anexo(s) incluído(s) com sucesso! Você pode preencher ou editar os títulos abaixo.`);
        }
    } catch (e) {
        console.error('[ANEXOS_CONTRATO] Erro ao enviar arquivos:', e);
        if (typeof Swal !== 'undefined') Swal.fire('Erro ao anexar', e.message || 'Não foi possível enviar o(s) arquivo(s).', 'error');
    } finally {
        if (btnUpload) {
            btnUpload.disabled = false;
            btnUpload.innerHTML = htmlOrig || `<i class="ph ph-upload-simple" style="font-size:1rem; font-weight:700;"></i> Incluir Documento(s) Anexo(s)`;
        }
    }
};

window.salvarTituloAnexoContrato = async function(anexoId, novoTitulo) {
    const propId = Number(_propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId || !anexoId) return;
    const itemCache = (window._anexosContratoCache || []).find(x => Number(x.id) === Number(anexoId));
    const titLimpo = String(novoTitulo ?? '').trim();
    if (itemCache && String(itemCache.titulo || '').trim() === titLimpo) return;

    try {
        const res = await apiPut(`/propostas/${propId}/anexos-contrato/${anexoId}`, { titulo: titLimpo });
        if (res && res.anexo) {
            if (itemCache) itemCache.titulo = res.anexo.titulo;
            const stEl = document.getElementById(`prop-anexo-status-${anexoId}`);
            if (stEl) {
                stEl.style.display = 'inline';
                setTimeout(() => { if (stEl) stEl.style.display = 'none'; }, 1800);
            }
        }
    } catch (e) {
        console.warn('[ANEXOS_CONTRATO] Erro ao atualizar título do anexo:', e);
    }
};

window.abrirArquivoAnexoContrato = function(anexoId, download = false) {
    const propId = Number(_propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId || !anexoId) return;
    const url = window._obterUrlArquivoAnexoContrato(anexoId, download, propId);
    if (url) window.open(url, '_blank');
};

window.excluirAnexoContrato = async function(anexoId, nomeArquivo) {
    const propId = Number(_propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId || !anexoId) return;

    if (typeof Swal !== 'undefined') {
        const conf = await Swal.fire({
            title: 'Remover anexo?',
            text: `Deseja remover "${nomeArquivo || 'este anexo'}" da lista do contrato?`,
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#dc2626',
            cancelButtonColor: '#64748b',
            confirmButtonText: 'Sim, remover',
            cancelButtonText: 'Cancelar'
        });
        if (!conf.isConfirmed) return;
    } else if (!confirm(`Deseja remover "${nomeArquivo || 'este anexo'}" do contrato?`)) {
        return;
    }

    try {
        const token = localStorage.getItem('erp_token') || localStorage.getItem('token') || '';
        const resp = await fetch(`/api/propostas/${propId}/anexos-contrato/${anexoId}`, {
            method: 'DELETE',
            headers: token ? { 'Authorization': `Bearer ${token}` } : {}
        });
        const data = await resp.json().catch(() => ({}));
        if (!resp.ok || data.error) throw new Error(data.error || 'Erro ao remover anexo.');

        window._anexosContratoCache = (window._anexosContratoCache || []).filter(x => Number(x.id) !== Number(anexoId));
        window.renderizarListaAnexosContrato(window._anexosContratoCache);
        if (typeof mostrarToastSucesso === 'function') mostrarToastSucesso('Anexo removido da lista do contrato.');
    } catch (e) {
        if (typeof Swal !== 'undefined') Swal.fire('Erro', e.message || 'Erro ao remover anexo.', 'error');
    }
};

/* ── Quadro OS DO CONTRATO (fechado com seta para baixo e detalhes expansíveis ao clicar) ── */
window._osContratoCache = [];
window._osContratoDetalhesAbertos = {};

window.carregarOsContratoAtivo = async function(propIdOpcional, mostrarFeedback = false) {
    const propId = Number(propIdOpcional || _propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId) {
        window._osContratoCache = [];
        window.renderizarListaOsContrato([]);
        return;
    }
    try {
        const res = await apiGet(`/propostas/${propId}/os-contrato`);
        const lista = (res && Array.isArray(res.os_list)) ? res.os_list : [];
        window._osContratoCache = lista;
        window.renderizarListaOsContrato(lista);
        if (mostrarFeedback && typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`Lista de OS atualizada (${lista.length} encontrada(s)).`);
        }
    } catch (e) {
        console.warn('[OS_CONTRATO] Erro ao carregar OS do contrato:', e);
        window.renderizarListaOsContrato([]);
    }
};

window.toggleDetalheItemOsContrato = function(osId, event) {
    if (event) event.stopPropagation();
    const key = String(osId);
    const detEl = document.getElementById(`prop-os-contrato-det-${key}`);
    const caretEl = document.getElementById(`prop-os-contrato-caret-${key}`);
    if (!detEl) return;
    const aberto = detEl.style.display !== 'none';
    const novo = !aberto;
    window._osContratoDetalhesAbertos[key] = novo;
    detEl.style.display = novo ? 'block' : 'none';
    if (caretEl) {
        caretEl.style.transform = novo ? 'rotate(180deg)' : 'rotate(0deg)';
    }
};

window.renderizarListaOsContrato = function(lista) {
    const arr = Array.isArray(lista) ? lista : (window._osContratoCache || []);
    const badge = document.getElementById('prop-os-contrato-count-badge');
    if (badge) badge.textContent = `${arr.length} OS`;

    const wrap = document.getElementById('prop-os-contrato-lista-wrap');
    if (!wrap) return;

    if (!arr.length) {
        wrap.innerHTML = `
            <div style="text-align:center; color:#64748b; font-size:0.82rem; padding:0.85rem; background:#ffffff; border:1px dashed #cbd5e1; border-radius:8px;">
                Nenhuma Ordem de Serviço (OS) vinculada a este contrato até o momento.
            </div>
        `;
        return;
    }

    const fmtDataBr = (iso) => {
        const s = String(iso || '').trim();
        const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
        return m ? `${m[3]}/${m[2]}/${m[1]}` : (s || '—');
    };

    const parseJsonList = (val) => {
        if (!val) return [];
        if (Array.isArray(val)) return val;
        try {
            const p = JSON.parse(val);
            return Array.isArray(p) ? p : [];
        } catch (_) {
            return String(val).split(',').map(x => x.trim()).filter(Boolean);
        }
    };

    wrap.innerHTML = `
        <div style="display:flex; flex-direction:column; gap:8px;">
            ${arr.map(os => {
                const key = String(os.id || os.numero_os || Math.random());
                const estaAberto = Boolean(window._osContratoDetalhesAbertos && window._osContratoDetalhesAbertos[key]);
                const tServ = String(os.tipo_servico || os.tipo_os || 'OS').trim();
                const tServUp = tServ.toUpperCase();
                let badgeBg = '#e0f2fe';
                let badgeColor = '#0369a1';
                let badgeBorder = '#7dd3fc';
                if (tServUp.includes('ENTREGA')) { badgeBg = '#dcfce7'; badgeColor = '#15803d'; badgeBorder = '#86efac'; }
                else if (tServUp.includes('RETIRADA')) { badgeBg = '#fef9c3'; badgeColor = '#854d0e'; badgeBorder = '#fde047'; }
                else if (tServUp.includes('MANUTEN') || tServUp.includes('VAC')) { badgeBg = '#f1f5f9'; badgeColor = '#334155'; badgeBorder = '#cbd5e1'; }

                const prodsArr = parseJsonList(os.produtos);
                const prodsHtml = prodsArr.length
                    ? prodsArr.map(p => {
                        if (p && typeof p === 'object') {
                            return `<span style="background:#1e40af; color:#fff; padding:2px 8px; border-radius:999px; font-size:0.74rem; font-weight:600;">${_escHtmlProp(p.desc || p.produto || '')}${p.qtd ? ` (${_escHtmlProp(p.qtd)})` : ''}</span>`;
                        }
                        return `<span style="background:#1e40af; color:#fff; padding:2px 8px; border-radius:999px; font-size:0.74rem; font-weight:600;">${_escHtmlProp(String(p))}</span>`;
                    }).join(' ')
                    : '<span style="color:#94a3b8;">—</span>';

                const diasArr = parseJsonList(os.dias_semana);
                const diasStr = diasArr.length ? diasArr.join(', ') : '—';
                const habArr = parseJsonList(os.habilidades);
                const habStr = habArr.length ? habArr.join(', ') : (os.habilidades || '—');
                const varArr = parseJsonList(os.variaveis);
                const varStr = varArr.length ? varArr.join(', ') : (os.variaveis || '—');
                const endCompleto = [os.endereco, os.complemento, os.cep ? `CEP: ${os.cep}` : ''].filter(Boolean).join(' — ') || '—';
                const horarioTurno = [os.hora_inicio && os.hora_fim ? `${os.hora_inicio} às ${os.hora_fim}` : (os.hora_inicio || os.hora_fim || ''), os.turno || ''].filter(Boolean).join(' • ') || '—';

                return `
                    <div style="background:#ffffff; border:1px solid #bfdbfe; border-radius:8px; overflow:hidden;">
                        <div onclick="${os.is_os_comercial ? `window.abrirOsComercialDaProposta(${Number(os.proposta_id)})` : `window.toggleDetalheItemOsContrato('${key}', event)`}"
                            style="padding:0.55rem 0.8rem; display:flex; align-items:center; justify-content:space-between; gap:10px; cursor:pointer; user-select:none; background:#f8fafc; transition:background 0.15s;"
                            onmouseover="this.style.background='#eff6ff'" onmouseout="this.style.background='#f8fafc'">
                            <div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; flex:1;">
                                <span style="background:#16a34a; color:#ffffff; font-weight:800; font-size:0.75rem; padding:2px 9px; border-radius:6px;">
                                    OS Nº ${_escHtmlProp(os.numero_os || os.id)}
                                </span>
                                <span style="background:${badgeBg}; color:${badgeColor}; border:1px solid ${badgeBorder}; font-weight:800; font-size:0.73rem; padding:2px 8px; border-radius:6px;">
                                    ${_escHtmlProp(os.is_os_comercial ? (os.tipo_servico || 'Envio') : tServ)}
                                </span>
                                ${os.status_os ? `<span style="background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd; font-weight:800; font-size:0.71rem; padding:2px 8px; border-radius:999px;">${_escHtmlProp(os.status_os)}</span>` : ''}
                                <span style="font-size:0.78rem; font-weight:700; color:#334155;">
                                    <i class="ph ph-calendar-blank"></i> ${_escHtmlProp(fmtDataBr(os.data_os))}
                                </span>
                                <span style="font-size:0.76rem; color:#64748b; max-width:420px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                                    ${_escHtmlProp(os.endereco || '')}
                                </span>
                            </div>
                            <div style="display:flex; align-items:center; gap:6px; flex-shrink:0;">
                                <span style="font-size:0.72rem; font-weight:700; color:#2563eb;">${os.is_os_comercial ? 'Abrir OS Comercial' : 'Ver detalhes'}</span>
                                <button type="button" onclick="window.toggleDetalheItemOsContrato('${key}', event)" title="Abrir / Fechar detalhes da OS"
                                    style="display:inline-flex; align-items:center; justify-content:center; width:24px; height:24px; border-radius:6px; border:1px solid #93c5fd; background:#dbeafe; color:#1e40af; cursor:pointer;">
                                    <i id="prop-os-contrato-caret-${key}" class="ph ph-caret-down" style="font-size:0.88rem; font-weight:700; transition:transform 0.2s; transform:${estaAberto ? 'rotate(180deg)' : 'rotate(0deg)'};"></i>
                                </button>
                            </div>
                        </div>
                        <div id="prop-os-contrato-det-${key}" style="display:${estaAberto ? 'block' : 'none'}; padding:0.75rem 0.9rem; border-top:1px solid #e2e8f0; background:#ffffff; font-size:0.8rem; color:#1e293b;">
                            <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(210px, 1fr)); gap:0.55rem 0.9rem; margin-bottom:0.6rem;">
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Número da OS / Contrato</strong>OS ${_escHtmlProp(os.numero_os || '—')} • Contrato ${_escHtmlProp(os.contrato || '—')}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Tipo de Serviço</strong>${_escHtmlProp(os.is_os_comercial ? (os.tipo_servico || 'Envio') : tServ)}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Data / Horário / Turno</strong>${_escHtmlProp(fmtDataBr(os.data_os))} (${_escHtmlProp(horarioTurno)})</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Dias da Semana</strong>${_escHtmlProp(diasStr)}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Responsável / Contato</strong>${_escHtmlProp([os.responsavel, os.telefone, os.email].filter(Boolean).join(' • ') || '—')}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Patrimônio</strong>${_escHtmlProp(os.patrimonio || '—')}</div>
                                <div style="grid-column:1 / -1;"><strong style="color:#64748b; font-size:0.73rem; display:block;">Endereço da OS</strong>${_escHtmlProp(endCompleto)}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Habilidades</strong>${_escHtmlProp(habStr)}</div>
                                <div><strong style="color:#64748b; font-size:0.73rem; display:block;">Variáveis</strong>${_escHtmlProp(varStr)}</div>
                            </div>
                            <div style="margin-bottom:0.5rem;">
                                <strong style="color:#64748b; font-size:0.73rem; display:block; margin-bottom:4px;">Produtos / Equipamentos da OS</strong>
                                <div style="display:flex; flex-wrap:wrap; gap:5px;">${prodsHtml}</div>
                            </div>
                            ${(os.observacoes || os.observacoes_internas) ? `
                                <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(240px, 1fr)); gap:0.55rem; margin-top:0.5rem; padding-top:0.5rem; border-top:1px dashed #e2e8f0;">
                                    ${os.observacoes ? `<div><strong style="color:#64748b; font-size:0.73rem; display:block;">Observações da OS</strong><div style="white-space:pre-wrap; color:#334155;">${_escHtmlProp(os.observacoes)}</div></div>` : ''}
                                    ${os.observacoes_internas ? `<div><strong style="color:#64748b; font-size:0.73rem; display:block;">Observações Internas</strong><div style="white-space:pre-wrap; color:#334155;">${_escHtmlProp(os.observacoes_internas)}</div></div>` : ''}
                                </div>
                            ` : ''}
                        </div>
                    </div>
                `;
            }).join('')}
        </div>
    `;
};

window.gerarOsComercialDoContrato = async function(propIdOpcional) {
    const propId = Number(propIdOpcional || _propostasEditandoId || window._propostasEditandoId_contrato);
    if (!propId) return;
    try {
        const res = await apiPost(`/propostas/${propId}/gerar-os-comercial`, {});
        if (!res || !res.success) {
            Swal.fire('Aviso', (res && res.error) || 'Não foi possível gerar a OS deste contrato.', 'warning');
            return;
        }
        if (Array.isArray(_propostasData)) {
            const idx = _propostasData.findIndex(p => Number(p.id) === propId);
            if (idx >= 0) {
                _propostasData[idx].numero_os = res.numero_os;
                _propostasData[idx].status_os = res.status_os || 'EM ELABORAÇÃO';
                _propostasData[idx].os_criada_em = res.os_criada_em;
                _propostasData[idx].os_tipo_operacao = res.os_tipo_operacao || 'Envio';
            }
        }
        if (typeof window.atualizarVisibilidadeBotoesPosSalvoProposta === 'function') {
            window.atualizarVisibilidadeBotoesPosSalvoProposta();
        }
        if (typeof window.carregarOsContratoAtivo === 'function') {
            window.carregarOsContratoAtivo(propId);
        }
        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`OS Nº ${res.numero_os} gerada com sucesso (Tipo: ${res.os_tipo_operacao || 'Envio'} · Status: ${res.status_os || 'EM ELABORAÇÃO'})!`);
        }
        window.abrirOsComercialDaProposta(propId, res.os_tipo_operacao || '');
    } catch (e) {
        Swal.fire('Aviso', e.message || 'Erro ao gerar a OS.', 'warning');
    }
};

window.abrirOsComercialDaProposta = function(propId, tipoOperacaoForcado = '') {
    const idNum = Number(propId);
    if (!idNum) return;
    window._comercialOsAbrirPropostaId = idNum;
    window._comercialOsTipoOperacaoForcado = tipoOperacaoForcado || '';
    if (typeof navigateTo === 'function') {
        navigateTo('comercial-os');
    }
    setTimeout(() => {
        if (window._comercialOS && typeof window._comercialOS.carregarOsPorPropostaId === 'function') {
            window._comercialOS.carregarOsPorPropostaId(idNum, tipoOperacaoForcado || '');
        }
    }, 90);
};

