window._normalizarClausulaIntervenienteComMnemonicos = function(raw) {
    let s = String(raw || '').trim();
    if (!s) return window._padraoTextoLegalIntervenienteContrato();
    // Substitui cabeçalhos fixos antigos (ex: "11 – CLÁUSULA DÉCIMA – DA CIÊNCIA DO INTERVENIENTE", "10 – CLÁUSULA DÉCIMA – DA CIÊNCIA DO INTERVENIENTE" ou "CLÁUSULA – DA CIÊNCIA E ANUÊNCIA DO INTERVENIENTE") pelo mnemônico dinâmico
    s = s
        .replace(/(?:^|>|\n)\s*(?:\d+\s*[–-]\s*)?CL[ÁA]USULA(?:\s+[A-ZÁÉÍÓÚÂÊÔÃÕÇ]+)*(?:\s+[–-]\s*DA\s+CI[ÊE]NCIA(?:\s+E\s+ANU[ÊE]NCIA)?\s+DO\s+INTERVENIENTE)/gi, (m) => {
            const lead = m.startsWith('>') ? '>' : (m.startsWith('\n') ? '\n' : '');
            return `${lead}{{TITULO_CLAUSULA_INTERVENIENTE}} – DA CIÊNCIA DO INTERVENIENTE`;
        })
        .replace(/(?:^|>|\n)\s*\d+\.1\s*[–-]\s*(?=O\(A\))/gi, (m) => {
            const lead = m.startsWith('>') ? '>' : (m.startsWith('\n') ? '\n' : '');
            return `${lead}{{NUMERO_CLAUSULA_INTERVENIENTE}} – `;
        })
        .replace(/\$\{entidade_cliente_centralizador_razaosocial\}/gi, '{{INTERVENIENTE_RAZAO_SOCIAL}}');
    return s;
};

window._ordinalClausulaFeminino = function(num) {
    const n = Number(num) || 1;
    const mapa = {
        1: 'PRIMEIRA',
        2: 'SEGUNDA',
        3: 'TERCEIRA',
        4: 'QUARTA',
        5: 'QUINTA',
        6: 'SEXTA',
        7: 'SÉTIMA',
        8: 'OITAVA',
        9: 'NONA',
        10: 'DÉCIMA',
        11: 'DÉCIMA PRIMEIRA',
        12: 'DÉCIMA SEGUNDA',
        13: 'DÉCIMA TERCEIRA',
        14: 'DÉCIMA QUARTA',
        15: 'DÉCIMA QUINTA',
        16: 'DÉCIMA SEXTA',
        17: 'DÉCIMA SÉTIMA',
        18: 'DÉCIMA OITAVA',
        19: 'DÉCIMA NONA',
        20: 'VIGÉSIMA'
    };
    return mapa[n] || `${n}ª`;
};

window.calcularProximaClausulaInterveniente = function(clausulasBase) {
    const txt = String(clausulasBase || '')
        .replace(/<br\s*\/?>/gi, '\n')
        .replace(/<\/(div|p|h[1-6]|li|tr)>/gi, '\n')
        .replace(/<[^>]+>/g, '');
    let maxNum = 0;
    const linhas = txt.split(/\r?\n/);
    for (let i = 0; i < linhas.length; i++) {
        const ln = linhas[i].trim();
        if (/INTERVENIENTE/i.test(ln) && /CI[ÊE]NCIA/i.test(ln)) continue;
        const m = ln.match(/^(\d+)\s*[–-]\s*CL[ÁA]USULA\b/i);
        if (m) {
            const n = parseInt(m[1], 10);
            if (n > 0 && n < 100 && n > maxNum) maxNum = n;
        }
    }
    if (maxNum === 0) {
        const rgxSub = /(?:^|\n)\s*(\d+)\.\d+\s*[–.-]/g;
        let ms;
        while ((ms = rgxSub.exec(txt)) !== null) {
            const n = parseInt(ms[1], 10);
            if (n > 0 && n < 100 && n > maxNum) maxNum = n;
        }
    }
    const prox = (maxNum > 0 ? maxNum : 10) + 1;
    const ord = window._ordinalClausulaFeminino(prox);
    return {
        numero: prox,
        titulo: `${prox} – CLÁUSULA ${ord}`,
        subitem: `${prox}.1`
    };
};

/* Extrai ou migra a estrutura (Preâmbulo + Tabela de Dados do Cliente + Cláusulas + Assinaturas) do modelo */
window.extrairEstruturaModeloContrato = function(m) {
    if (!m) {
        return {
            v: 2,
            preambulo: '',
            quadro_cliente: window._padraoQuadroClienteContrato(),
            quadro_interveniente: window._padraoQuadroIntervenienteContrato(),
            clausulas: '',
            clausula_interveniente: window._padraoTextoLegalIntervenienteContrato(),
            assinaturas: window._padraoAssinaturasContrato(false)
        };
    }
    const ehInterveniente = String(m.codigo_tipo || m.nome || '').toUpperCase().includes('INTERVENIENTE');
    let parsedCaputs = null;
    try {
        if (m.caputs) {
            const p = typeof m.caputs === 'string' ? JSON.parse(m.caputs) : m.caputs;
            if (p && typeof p === 'object' && !Array.isArray(p) && p.v === 2) {
                parsedCaputs = p;
            }
        }
    } catch (_) {}

    const qCliPadrao = window._padraoQuadroClienteContrato();
    const qIntPadrao = window._padraoQuadroIntervenienteContrato();

    if (parsedCaputs) {
        let clauInterv = parsedCaputs.clausula_interveniente;
        if (clauInterv === undefined && ehInterveniente) {
            // Extrair cláusula de interveniente se já estiver nas cláusulas ou usar padrão
            const rawC = String(parsedCaputs.clausulas || m.texto_contrato || '');
            const mIdx = rawC.search(/(?:\{\{TITULO_CLAUSULA_INTERVENIENTE\}\}|\d*\s*[–-]?\s*CL[ÁA]USULA)[^<\n]*INTERVENIENTE/i);
            clauInterv = mIdx >= 0 ? rawC.slice(mIdx).trim() : window._padraoTextoLegalIntervenienteContrato();
        }
        return {
            v: 2,
            preambulo: parsedCaputs.preambulo !== undefined ? String(parsedCaputs.preambulo) : '',
            quadro_cliente: Object.assign({}, qCliPadrao, parsedCaputs.quadro_cliente || {}),
            quadro_interveniente: Object.assign({}, qIntPadrao, parsedCaputs.quadro_interveniente || {}),
            clausulas: parsedCaputs.clausulas !== undefined ? String(parsedCaputs.clausulas) : String(m.texto_contrato || ''),
            clausula_interveniente: window._normalizarClausulaIntervenienteComMnemonicos(clauInterv !== undefined ? String(clauInterv) : window._padraoTextoLegalIntervenienteContrato()),
            assinaturas: Array.isArray(parsedCaputs.assinaturas)
                ? parsedCaputs.assinaturas
                : window._padraoAssinaturasContrato(ehInterveniente),
            assinaturas_avarias: Array.isArray(parsedCaputs.assinaturas_avarias)
                ? parsedCaputs.assinaturas_avarias
                : window._padraoAssinaturasContrato(ehInterveniente)
        };
    }

    // Migração automática do texto bruto antigo (separa Preâmbulo, remove linhas soltas de qualificação do cliente e mantém Cláusulas)
    const rawTexto = String(m.texto_contrato || '');
    const linhas = rawTexto.split(/\r?\n/);
    const preambuloLinhas = [];
    const clausulasLinhas = [];
    let chegouClausulas = false;
    let chegouQualificacao = false;

    const rgxQualifLine = /^(Locat[áa]ria\s*\/\s*Contratante|Contratante|Interveniente|Endere[çc]o(?: de Faturamento)?|Cidade|Estado|CNPJ(?:\/CPF)?|Telefone|Contato|CEP|Inscri[çc][ãa]o Estadual|E-mail|Tel\.\s*Contato)\s*:/i;
    const rgxInicioClausula = /^(\d+\s*[–-]\s*CL[ÁA]USULA|CL[ÁA]USULA\s+PRIMEIRA)/i;

    for (let i = 0; i < linhas.length; i++) {
        const ln = linhas[i];
        const trimLn = ln.trim();
        if (!chegouClausulas && rgxInicioClausula.test(trimLn)) {
            chegouClausulas = true;
        }
        if (chegouClausulas) {
            clausulasLinhas.push(ln);
        } else if (rgxQualifLine.test(trimLn)) {
            chegouQualificacao = true;
            // Linha de qualificação agora faz parte da Tabela de Dados do Cliente
        } else if (!chegouQualificacao) {
            preambuloLinhas.push(ln);
        } else if (trimLn) {
            // Qualquer linha entre a qualificação e a primeira cláusula (ex: parágrafo do Interveniente)
            if (/^E\s+como\s+INTERVENIENTE/i.test(trimLn)) {
                // O cabeçalho do interveniente já fica representado pelo quadro de interveniente
            } else {
                clausulasLinhas.push(ln);
            }
        }
    }

    const joinedClau = clausulasLinhas.join('\n').trim();
    const mIdxMig = joinedClau.search(/(?:\{\{TITULO_CLAUSULA_INTERVENIENTE\}\}|\d*\s*[–-]?\s*CL[ÁA]USULA)[^<\n]*INTERVENIENTE/i);
    const clauIntervMig = window._normalizarClausulaIntervenienteComMnemonicos(
        (ehInterveniente && mIdxMig >= 0) ? joinedClau.slice(mIdxMig).trim() : window._padraoTextoLegalIntervenienteContrato()
    );

    return {
        v: 2,
        preambulo: preambuloLinhas.join('\n').trim(),
        quadro_cliente: qCliPadrao,
        quadro_interveniente: qIntPadrao,
        clausulas: joinedClau,
        clausula_interveniente: clauIntervMig,
        assinaturas: window._padraoAssinaturasContrato(ehInterveniente),
        assinaturas_avarias: window._padraoAssinaturasContrato(ehInterveniente)
    };
};

window.formatarTelefoneTabelaContrato = function(raw) {
    const s = String(raw || '').trim();
    if (!s || s === '—' || s === '-') return s || '—';
    let d = s.replace(/\D+/g, '');
    if (!d) return s;
    if ((d.length === 12 || d.length === 13) && d.startsWith('55')) d = d.slice(2);
    if ((d.length === 11 || d.length === 12) && d.startsWith('0')) d = d.slice(1);
    if (d.length > 11) d = d.slice(0, 11);
    if (d.length >= 3) return `(${d.slice(0, 2)})${d.slice(2)}`;
    return d;
};

/* Renderiza a Tabela de Dados do Cliente (somente leitura para PDF/Impressão) */
