window.enviarTopoPersonalizadoModeloContrato = async function(inputEl) {
    const file = inputEl && inputEl.files && inputEl.files[0];
    const m = window._modeloContratoAtivo;
    if (!file || !m || !m.id) return;
    const fd = new FormData();
    fd.append('arquivo', file);
    try {
        Swal.fire({ title: 'Salvando topo do contrato...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
        const token = window.currentToken || localStorage.getItem('erp_token') || localStorage.getItem('token') || sessionStorage.getItem('token') || '';
        const resp = await fetch(`/api/comercial/modelos-contrato/${m.id}/topo`, {
            method: 'POST',
            headers: token ? { 'Authorization': 'Bearer ' + token } : {},
            body: fd
        });
        const j = await resp.json().catch(() => ({}));
        Swal.close();
        if (!resp.ok || !j.success) throw new Error(j.error || 'Não foi possível salvar a imagem de topo.');
        if (j.modelo) {
            m.topo_r2_key = j.modelo.topo_r2_key;
            m.topo_mime_type = j.modelo.topo_mime_type;
            m.topo_url = j.modelo.topo_url;
            const idx = (window._modelosContratoList || []).findIndex(x => Number(x.id) === Number(m.id));
            if (idx >= 0) window._modelosContratoList[idx] = JSON.parse(JSON.stringify(m));
            window._comercialModelosContrato = window._modelosContratoList;
        }
        window.atualizarPreviewModeloContratoAtivo();
        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso('Topo do contrato atualizado com sucesso!');
        }
    } catch (e) {
        Swal.fire('Erro', e.message || 'Erro ao enviar imagem de topo.', 'error');
    } finally {
        if (inputEl) inputEl.value = '';
    }
};

window.removerTopoPersonalizadoModeloContrato = async function() {
    const m = window._modeloContratoAtivo;
    if (!m || !m.id) return;
    const conf = await Swal.fire({
        title: 'Restaurar topo padrão?',
        text: `O tipo de contrato "${m.nome}" voltará a usar o topo padrão da empresa.`,
        icon: 'question',
        showCancelButton: true,
        confirmButtonColor: '#dc2626',
        confirmButtonText: 'Sim, restaurar padrão',
        cancelButtonText: 'Cancelar'
    });
    if (!conf.isConfirmed) return;
    try {
        const token = window.currentToken || localStorage.getItem('erp_token') || localStorage.getItem('token') || sessionStorage.getItem('token') || '';
        const resp = await fetch(`/api/comercial/modelos-contrato/${m.id}/topo`, {
            method: 'DELETE',
            headers: token ? { 'Authorization': 'Bearer ' + token } : {}
        });
        const j = await resp.json().catch(() => ({}));
        if (!resp.ok || !j.success) throw new Error(j.error || 'Erro ao restaurar topo padrão.');
        m.topo_r2_key = null;
        m.topo_mime_type = null;
        m.topo_url = '';
        const idx = (window._modelosContratoList || []).findIndex(x => Number(x.id) === Number(m.id));
        if (idx >= 0) window._modelosContratoList[idx] = JSON.parse(JSON.stringify(m));
        window._comercialModelosContrato = window._modelosContratoList;
        window.atualizarPreviewModeloContratoAtivo();
        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso('Topo padrão restaurado!');
        }
    } catch (e) {
        Swal.fire('Erro', e.message || 'Erro ao restaurar topo padrão.', 'error');
    }
};

window.copiarMnemonicoContratoParaAreaTransferencia = function(tag) {
    const t = String(tag || '').trim();
    if (!t) return;
    const avisarCopia = () => {
        if (typeof mostrarToastSucesso === 'function') {
            mostrarToastSucesso(`Mnemônico ${t} copiado! Cole onde quiser no contrato (Ctrl+V).`);
        } else if (typeof Swal !== 'undefined') {
            Swal.fire({
                toast: true,
                position: 'top-end',
                icon: 'success',
                title: `Mnemônico ${t} copiado!`,
                showConfirmButton: false,
                timer: 2200
            });
        }
    };
    if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        navigator.clipboard.writeText(t).then(avisarCopia).catch(() => {
            try {
                const ta = document.createElement('textarea');
                ta.value = t;
                ta.style.position = 'fixed';
                ta.style.opacity = '0';
                document.body.appendChild(ta);
                ta.select();
                document.execCommand('copy');
                document.body.removeChild(ta);
            } catch (_) {}
            avisarCopia();
        });
    } else {
        try {
            const ta = document.createElement('textarea');
            ta.value = t;
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            document.body.removeChild(ta);
        } catch (_) {}
        avisarCopia();
    }
};

window.renderizarChipsMnemonicosContrato = function() {
    const box = document.getElementById('mc-mnemonicos-chips-container');
    if (!box) return;
    const norm = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
    const q = norm(document.getElementById('mc-mnemonico-search')?.value || '');
    const m = window._modeloContratoAtivo;
    const tipoAtivo = m ? (m.codigo_tipo || m.nome || '') : '';

    const catalogoCompleto = [];
    (window.CONTRATO_MNEMONICOS_CATALOGO || []).forEach(item => {
        catalogoCompleto.push(item);
    });

    // Adiciona dinamicamente todos os mnemônicos de Custos de Reposição cadastrados (criados/excluídos automaticamente)
    const fmtMRep = (v) => Number(v || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    (window._valoresReposicaoList || []).forEach(rep => {
        if (rep && rep.mnemonico && !catalogoCompleto.some(c => c.tag === rep.mnemonico)) {
            catalogoCompleto.push({
                tag: String(rep.mnemonico).trim(),
                label: `Reposição: ${rep.nome} (R$ ${fmtMRep(rep.valor)})`,
                categoria: 'Custos de Reposição'
            });
        }
    });

    const lista = catalogoCompleto.filter(item => {
        if (!window.mnemonicoPertenceAoTipoContrato(item, tipoAtivo)) return false;
        if (!q) return true;
        return norm(item.tag).includes(q) || norm(item.label).includes(q) || norm(item.categoria).includes(q);
    });

    if (!lista.length) {
        box.innerHTML = '<span style="font-size:0.75rem; color:#64748b; padding:4px;">Nenhum mnemônico encontrado para este filtro.</span>';
        return;
    }

    box.innerHTML = lista.map(item => `
        <button type="button" onmousedown="event.preventDefault(); window.copiarMnemonicoContratoParaAreaTransferencia('${item.tag}')"
            title="Clique para copiar ${_escHtmlProp(item.tag)} (${_escHtmlProp(item.label)}) e colar onde quiser no contrato"
            style="background:#fff; border:1px solid #c4b5fd; border-radius:6px; padding:4px 8px; cursor:pointer; display:inline-flex; align-items:center; gap:5px; font-size:0.74rem; color:#1e293b; transition:all 0.12s; height:auto !important;"
            onmouseover="this.style.background='#ede9fe'; this.style.borderColor='#7048e8'"
            onmouseout="this.style.background='#fff'; this.style.borderColor='#c4b5fd'">
            <i class="ph ph-copy" style="color:#7048e8; font-size:0.8rem;"></i>
            <code style="font-weight:800; color:#5b21b6; font-size:0.73rem;">${_escHtmlProp(item.tag)}</code>
            <span style="color:#475569; font-size:0.72rem;">${_escHtmlProp(item.label)}</span>
        </button>
    `).join('');
};

window.inserirMnemonicoNoTextoContrato = function(tag) {
    window.copiarMnemonicoContratoParaAreaTransferencia(tag);
};

window._sincronizarEstruturaParaModeloContratoAtivo = function() {
    const m = window._modeloContratoAtivo;
    const est = window._estruturaContratoAtivo;
    if (!m || !est) return;

    const inpTitSheet = document.getElementById('mc-sheet-edit-titulo');
    if (inpTitSheet) {
        m.titulo_contrato = inpTitSheet.isContentEditable ? inpTitSheet.innerHTML : inpTitSheet.value;
    }

    const inpPre = document.getElementById('mc-edit-preambulo');
    if (inpPre) {
        est.preambulo = inpPre.isContentEditable ? inpPre.innerHTML : inpPre.value;
    }

    const inpClau = document.getElementById('mc-edit-texto');
    if (inpClau) {
        const ehInterv = String(m.codigo_tipo || m.nome || '').toUpperCase().includes('INTERVENIENTE');
        const valClau = inpClau.isContentEditable ? inpClau.innerHTML : inpClau.value;
        est.clausulas = valClau;
        if (ehInterv) {
            est.clausula_interveniente = valClau;
        }
    }

    document.querySelectorAll('#mc-live-preview [data-q-cli]').forEach(inp => {
        const k = inp.getAttribute('data-q-cli');
        const val = inp.tagName === 'INPUT' || inp.tagName === 'TEXTAREA' ? inp.value : (inp.textContent || '').trim();
        if (k && est.quadro_cliente) est.quadro_cliente[k] = val;
    });

    document.querySelectorAll('#mc-live-preview [data-q-int]').forEach(inp => {
        const k = inp.getAttribute('data-q-int');
        const val = inp.tagName === 'INPUT' || inp.tagName === 'TEXTAREA' ? inp.value : (inp.textContent || '').trim();
        if (k && est.quadro_interveniente) est.quadro_interveniente[k] = val;
    });

    document.querySelectorAll('#mc-live-preview [data-ass-idx]').forEach(inp => {
        const idx = Number(inp.getAttribute('data-ass-idx'));
        const field = inp.getAttribute('data-ass-field');
        const grupo = inp.getAttribute('data-ass-grupo') === 'avarias' ? 'assinaturas_avarias' : 'assinaturas';
        if (Array.isArray(est[grupo]) && est[grupo][idx] && field) {
            est[grupo][idx][field] = inp.value;
        }
    });

    m.caputs = JSON.stringify(est);
    m.texto_contrato = [est.preambulo, est.clausulas].filter(Boolean).join('\n\n');
};

window.removerBlocoAssinaturaModeloContrato = function(idx, grupo = 'principal') {
    const est = window._estruturaContratoAtivo;
    if (!est) return;
    window._sincronizarEstruturaParaModeloContratoAtivo();
    const chave = grupo === 'avarias' ? 'assinaturas_avarias' : 'assinaturas';
    if (!Array.isArray(est[chave])) return;
    est[chave].splice(idx, 1);
    if (window._modeloContratoAtivo) {
        window._modeloContratoAtivo.caputs = JSON.stringify(est);
    }
    window.atualizarPreviewModeloContratoAtivo();
};

window.adicionarBlocoAssinaturaModeloContrato = function(grupo = 'principal') {
    const est = window._estruturaContratoAtivo;
    if (!est) return;
    window._sincronizarEstruturaParaModeloContratoAtivo();
    const chave = grupo === 'avarias' ? 'assinaturas_avarias' : 'assinaturas';
    if (!Array.isArray(est[chave])) est[chave] = [];
    const ehSegundo = est[chave].length === 1;
    est[chave].push(ehSegundo ? {
        titulo: 'LOCADORA / CONTRATADA',
        linha1: 'AMÉRICA RENTAL EQUIPAMENTOS LTDA',
        linha2: 'CNPJ: 03.434.448/0001-01'
    } : {
        titulo: 'LOCATÁRIA / CONTRATANTE',
        linha1: '{{CLIENTE_RAZAO_SOCIAL}}',
        linha2: 'CNPJ/CPF: {{CLIENTE_CNPJ}}'
    });
    if (window._modeloContratoAtivo) {
        window._modeloContratoAtivo.caputs = JSON.stringify(est);
    }
    window.atualizarPreviewModeloContratoAtivo();
};

